-- Staging recovery only; existing production tables must not be recreated.
-- Verified with rollback tests for event/task favorites and focus sessions.
begin;
create table public.favorites(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,task_id uuid references public.tasks(id) on delete cascade,event_id uuid references public.events(id) on delete cascade,created_at timestamptz not null default now(),constraint favorites_exactly_one_target check ((task_id is not null)<>(event_id is not null))); create unique index favorites_user_task_unique on public.favorites(user_id,task_id) where task_id is not null; create unique index favorites_user_event_unique on public.favorites(user_id,event_id) where event_id is not null; create index favorites_user_created_idx on public.favorites(user_id,created_at desc); alter table public.favorites enable row level security; revoke all on public.favorites from public,anon,authenticated; grant select,insert,delete on public.favorites to authenticated; grant all on public.favorites to service_role; create policy favorites_select_own on public.favorites for select to authenticated using ((select auth.uid())=user_id); create policy favorites_delete_own on public.favorites for delete to authenticated using ((select auth.uid())=user_id); create policy favorites_insert_owned_target on public.favorites for insert to authenticated with check ((select auth.uid())=user_id and ((task_id is not null and exists(select 1 from public.tasks t where t.id=favorites.task_id and t.user_id=(select auth.uid()))) or (event_id is not null and exists(select 1 from public.events e where e.id=favorites.event_id and e.user_id=(select auth.uid()))))); create table public.focus_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,duration_minutes integer not null check(duration_minutes>0 and duration_minutes<=1440),completed_at timestamptz not null default now()); create index focus_sessions_user_completed_idx on public.focus_sessions(user_id,completed_at desc); alter table public.focus_sessions enable row level security; revoke all on public.focus_sessions from public,anon,authenticated; grant select,insert on public.focus_sessions to authenticated; grant all on public.focus_sessions to service_role; create policy "Users can insert own focus sessions" on public.focus_sessions for insert to authenticated with check ((select auth.uid())=user_id); create policy "Users can read own focus sessions" on public.focus_sessions for select to authenticated using ((select auth.uid())=user_id);
commit;
